def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        safe_bid = DAILY_SALARY * 0.35
        return float(min(budget, safe_bid))

    prev_bids = []
    cindy_bid = None
    david_bid = None
    max_opp_req = WATER_REQ
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            max_opp_req = max(max_opp_req, opp.get('water_requirement', WATER_REQ))
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if oid == 'Cindy':
                    cindy_bid = float(bid)
                elif oid == 'David':
                    david_bid = float(bid)

    total_players = 1 + len(alive)
    approx_winners = int(max(1, supply // max_opp_req))
    scarcity = approx_winners < total_players

    highest_prev = max(prev_bids) if prev_bids else 0.0
    moderate_anchor = david_bid if david_bid is not None else min(highest_prev, 95.0)
    bully_anchor = cindy_bid if cindy_bid is not None else highest_prev

    urgent = hp <= 3 or no_water_days >= 1
    critical = hp <= 2 or no_water_days >= 2

    if critical:
        bid = max(DAILY_SALARY * 0.95, moderate_anchor + 6.0)
        if scarcity:
            bid = max(bid, min(bully_anchor + 1.0, DAILY_SALARY * 1.55))
        return float(min(budget, bid))

    if scarcity:
        if urgent:
            bid = max(DAILY_SALARY * 0.9, moderate_anchor + 4.0)
        else:
            bid = max(DAILY_SALARY * 0.72, moderate_anchor + 2.0)
        if bully_anchor >= 120 and hp >= 5 and no_water_days == 0:
            bid = min(bid, DAILY_SALARY * 0.78)
        return float(min(budget, bid))

    if urgent:
        bid = max(DAILY_SALARY * 0.82, moderate_anchor + 1.5)
        return float(min(budget, bid))

    if bully_anchor >= 120:
        bid = DAILY_SALARY * 0.42
    elif moderate_anchor >= 80:
        bid = DAILY_SALARY * 0.52
    else:
        bid = DAILY_SALARY * 0.58

    if hp >= 7 and no_water_days == 0:
        bid *= 0.95

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        try:
            if opp.get('alive', False):
                alive_opps.append(opp)
        except Exception:
            pass

    if my_budget <= 0:
        return 0.0

    # Base bid: aim to be competitive but not maximal.
    # Tight supply => higher bid.
    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_ratio = max(0.0, min(1.0, supply_ratio))
    tightness = 1.0 - supply_ratio  # 1 when supply is MIN_SUPPLY

    # Reaction to yesterday's pressure: use only previous_trace bid.
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        if prev:
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    # Estimate opponent aggressiveness from yesterday.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        median_prev_bid = sorted(yesterday_bids)[len(yesterday_bids)//2]
    else:
        highest_prev_bid = 0.0
        median_prev_bid = DAILY_SALARY * 0.6

    # If my hp is low or I've already missed water, bid more.
    urgency = 0.0
    if my_hp <= 2:
        urgency = 1.0
    elif my_hp <= 4:
        urgency = 0.7
    else:
        urgency = 0.3

    if my_no_water_days >= 2:
        urgency = min(1.0, urgency + 0.3)

    # Target bid: slightly above median, adjusted by urgency and tightness.
    base_target = median_prev_bid * (0.95 + 0.25 * tightness)
    urgency_boost = DAILY_SALARY * (0.15 + 0.35 * urgency)  # 0.195..0.5 of DAILY_SALARY
    target = base_target + urgency_boost

    # If yesterday top bids were very high, ensure we can beat them sometimes.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        target = max(target, highest_prev_bid * (0.92 - 0.1 * (1.0 - urgency)))

    # Keep within budget and reasonable fraction of daily salary.
    max_affordable = my_budget
    # Hard cap to avoid reckless spending; scale cap with urgency.
    cap = DAILY_SALARY * (0.85 + 0.2 * urgency)
    bid = min(max_affordable, cap, target)

    # Final sanity floor/ceiling.
    if bid < 0:
        bid = 0.0
    return float(bid)
